function greaterThanSiblingNumber(spec, numeric) {
  const sibling = Number(spec.siblingValue);
  if (!Number.isFinite(sibling)) return "";
  return numeric > sibling ? "" : `maxValue must stay above ${siblingLabel(spec)} ${spec.siblingValue} for slider range controls`;
}

function authorizeSubjectPropertyMutation(input, helpers) {
  const { semantic, actor, combinedFacts, subject, operation } = input;
  const authority = helpers.resolveAuthority(semantic, actor, combinedFacts, subject);
  if (authority.allowed) return;
  helpers.fail(helpers.issue(
    POLICY.deniedDiagnostic,
    `Actor ${actor} lacks subject mutation authority for ${subject}.`,
    {
      actor, subject, operation,
      ...(authority.helperTargets.length ? { helperTargets: [...authority.helperTargets] } : {}),
    },
  ), { statusCode: POLICY.deniedStatus });
}

function intrinsicSlotPrompt(slot, subject, record, typedRecord, mode) {
  const adding = [mode === POLICY.addMode, slotIsMany(slot)].includes(true);
  const choices = Array.isArray(slot.allowed) && slot.allowed.length ? slot.allowed : null;
  const copy = slotEditorCopy(slot, adding ? POLICY.addMode : POLICY.setMode);
  const prompt = {
    message: `${copy.message} ${slot.predicate} ${copy.connector} ${subject}`,
    defaultValue: adding && !Object.hasOwn(record, slot.predicate)
      ? currentCanonicalDefault(slot, {}, {})
      : currentCanonicalDefault(slot, record, typedRecord),
    allowBlank: !adding && slot.cardinality === POLICY.optionalCardinality,
  };
  if (choices) {
    prompt.editorKind = POLICY.choiceEditor;
    prompt.choices = choices;
  } else if (slot.valueType) prompt.editorKind = slot.valueType;
  return prompt;
}

function propertyClearDelta(input, helpers) {
  const { combinedFacts, subject, slot, mutation, meta } = input;
  if (!POLICY.clearableCardinalities.has(slot.cardinality)) {
    helpers.fail(helpers.issue(POLICY.clearDiagnostic,
      `Slot ${slot.predicate} cannot be cleared because its cardinality is ${slot.cardinality}.`,
      { subject, predicate: slot.predicate, cardinality: slot.cardinality }));
  }
  const current = helpers.currentSingleValue(combinedFacts, subject, slot.predicate);
  if (current == null) {
    helpers.fail(helpers.issue(POLICY.notSetDiagnostic,
      `Subject ${subject} has no current ${slot.predicate} value to clear.`, { subject, predicate: slot.predicate }));
  }
  let target = current;
  if (helpers.hasPresentMutationValue(mutation)) target = helpers.canonicalizeMutationValue(slot, mutation, subject).value;
  if (slot.cardinality !== POLICY.unboundedCardinality && target !== current) {
    helpers.fail(helpers.issue(POLICY.notSetDiagnostic,
      `Subject ${subject} has no current ${slot.predicate} value ${target} to clear.`,
      { subject, predicate: slot.predicate, value: target, current }), { statusCode: POLICY.notFoundStatus });
  }
  return [helpers.deltaFact(subject, slot.predicate, target, POLICY.negativePolarity, meta)];
}

