function propertyRemovalDelta(input, helpers) {
  const { combinedFacts, subject, slot, mutation, meta } = input;
  const current = helpers.currentActiveValues(combinedFacts, subject, slot.predicate);
  if (slot.cardinality === POLICY.singleCardinality) {
    helpers.fail(helpers.issue(POLICY.removeDiagnostic,
      `Slot ${slot.predicate} cannot be removed because its cardinality is ${POLICY.singleCardinality}.`,
      { subject, predicate: slot.predicate, cardinality: slot.cardinality }));
  }
  if (!current.length) {
    helpers.fail(helpers.issue(POLICY.notSetDiagnostic,
      `Subject ${subject} has no current ${slot.predicate} value to remove.`, { subject, predicate: slot.predicate }));
  }
  const target = resolvePropertyRemovalTarget({ subject, slot, mutation, current }, helpers);
