function reclassifyAction(prog, subject, record, interfaces) {
  const choices = reclassificationChoiceDetails(prog, record, interfaces);
  return buildReclassifyAction({
    policyFacts: prog?.facts || prog,
    subject,
    prompt: {
      message: `Reclassify ${subject}. Known types: ${choices.map(choice => choice.value).join(", ")}`,
      defaultValue: selectedReclassificationDefault(choices),
      editorKind: "choice",
      choices: choices.map(choice => choice.value),
      choiceDetails: choices,
    },
  });
}
